-- db/community.sql — コミュニティ集計 (D1) の公開用スナップショット
--
-- ⚠️ これは完全バックアップではない。「誰が」を含む列 (user_id / device_id /
--    created_by / 表示名 / 引き継ぎコード) は意図的に一切含めていない。
--    このリポジトリは public なので、生ダンプを載せると個人情報が漏れる。
--    完全バックアップは tools/backup_d1.sh で db_backups_local/ に取ること。
--
-- 生成: python3 tools/export_community_snapshot.py --remote
--
-- CREATE TABLE も出すので、このファイルは単体で空の SQLite に流し込める
-- (Web 出面の書き出しが読む。INSERT だけだと受け手がスキーマを持つことになり、
--  列を足したときに片方だけ古いまま残る)。型は書かない: ここは読むだけの
-- スナップショットで、制約は D1 側が持っている。

CREATE TABLE IF NOT EXISTS "tags" ("id", "name", "description", "category", "color", "is_official", "status");
CREATE TABLE IF NOT EXISTS "idol_tag_master" ("id", "name", "description", "category", "color", "is_official", "status");
CREATE TABLE IF NOT EXISTS "unit_tag_master" ("id", "name", "description", "category", "color", "is_official", "status");
CREATE TABLE IF NOT EXISTS "song_tags" ("song_id", "tag_id", "vote_count");
CREATE TABLE IF NOT EXISTS "idol_tags" ("idol_id", "tag_id", "vote_count");
CREATE TABLE IF NOT EXISTS "unit_tags" ("unit_id", "tag_id", "vote_count");
CREATE TABLE IF NOT EXISTS "song_favorites" ("song_id", "count");
CREATE TABLE IF NOT EXISTS "penlight_color_set_votes" ("song_id", "color_set_key", "count");
CREATE TABLE IF NOT EXISTS "polls" ("id", "title", "description", "target_type", "created_at", "ends_at", "status");
CREATE TABLE IF NOT EXISTS "poll_entries" ("poll_id", "entity_id", "vote_count");

